import { expect, it } from 'bun:test';
import { nativeAcpFixture, nativeRows, replayText } from '/Volumes/XS1000/acoliver/projects/llxprt/branch-3/llxprt-code/packages/zed-acp/src/__tests__/support/native-acp-fault-fixture.ts';
it('preserves the prior live same-ID owner when replacement replay fails', async () => {
  const fixture = await nativeAcpFixture();
  try {
    const id = await fixture.create();
    await fixture.prompt(id);
    const path = await fixture.path(id);
    const before = await nativeRows(path);
    const prior = fixture.recordings.find((recording) => recording.getSessionId() === id);
    if (prior === undefined) throw new Error('Missing native prior owner');
    fixture.consume(async (update) => { if (replayText(update)) throw new Error('External replacement consumer failed'); });
    await expect(fixture.load(id)).rejects.toMatchObject({ code: -32603, data: { phase: 'replay' } });
    expect(prior.isActive()).toBe(true);
    expect(await fixture.locks()).toHaveLength(1);
    fixture.consume(async () => {});
    expect(await fixture.prompt(id)).toMatchObject({ stopReason: 'end_turn' });
    await fixture.peer.client.closeSession({ sessionId: id });
    expect((await nativeRows(path)).count).toBe(4);
    expect(await nativeRows(path, 2)).toStrictEqual({ ...before });
  } finally { await fixture.finish(); }
}, 30000);
